<script setup lang="ts">
// the record sheet as a form: whatever is written here wins, whatever is left empty follows the rules
import { computed, ref } from 'vue'
import { ABILITIES, ABILITY_NAME, SKILLS, SKILL_IDS, SKILL_NAME, signed, type Ability, type Damage, type Skill } from '../rules/base'
import { RACES, BACKGROUNDS } from '../rules/races'
import { CLASSES } from '../rules/classes'
import { ITEMS, item } from '../rules/items'
import { SPELLS, spell } from '../rules/spells'
import { DICE_RE, sheet, uid, type Hero, type Over } from '../rules/hero'
import { race } from '../rules/races'
import { lookOf } from '../engine/compose'
import Stage3D from './Stage3D.vue'
import Looks from './Looks.vue'
const p = defineProps<{ h: Hero; scan?: string }>(); const emit = defineEmits<{ scan: [f: File | null] }>(); const O = computed(() => p.h.over as Over & Required<Pick<Over, 'attacks' | 'spells' | 'feats'>>); const S = computed(() => sheet({ ...p.h, conds: [] })); const look = computed(() => ({ model: 'hero', hero: lookOf(p.h) })); const pic = ref<HTMLInputElement>()
const n = (v: string) => v.trim() === '' || !Number.isFinite(+v) ? undefined : Math.round(+v); const set = (k: keyof Over, v: any) => { const o = O.value as any; if (v === undefined) delete o[k]; else o[k] = v }; const setIn = (k: 'saves' | 'skills', id: string, v: number | undefined) => { const o = O.value as any; const m = { ...(o[k] ?? {}) }; if (v === undefined) delete m[id]; else m[id] = v; set(k, Object.keys(m).length ? m : undefined) }
const val = (e: Event) => (e.target as HTMLInputElement).value; const DT: Damage[] = ['slashing', 'piercing', 'bludgeoning', 'fire', 'cold', 'lightning', 'thunder', 'acid', 'poison', 'necrotic', 'radiant', 'psychic', 'force']; const badDice = (d?: string) => !!d && !DICE_RE.test(d.replace(/\s/g, ''))
const saveP = computed(() => O.value.saveP ?? S.value.saveProf); const togSave = (a: Ability) => { const l = [...saveP.value]; const i = l.indexOf(a); i >= 0 ? l.splice(i, 1) : l.push(a); set('saveP', l) }
const step = (k: Skill) => { const s = p.h.skills, x = p.h.expertise; if (x.includes(k)) { p.h.expertise = x.filter(q => q !== k); p.h.skills = s.filter(q => q !== k) } else if (s.includes(k)) p.h.expertise = [...x, k]; else p.h.skills = [...s, k] }
const addA = () => O.value.attacks.push({ id: 'p' + uid().slice(0, 6), name: '', hit: S.value.prof + S.value.mods.str, dmg: '1d8' + (S.value.mods.str ? signed(S.value.mods.str) : ''), type: 'slashing', reach: 5 }); const addS = () => O.value.spells.push({ id: 'q' + uid().slice(0, 6), name: '', lv: 1, kind: 'attack', dmg: '', type: 'fire', range: 60, time: 'action', text: '' }); const addF = () => O.value.feats.push({ name: '', text: '', rest: 'long' })
const ranged = (a: any, on: boolean) => { a.ranged = on; if (on) a.range ??= [80, 320]; else { a.range = undefined; a.reach ??= 5 } }
const sq = ref(''), iq = ref(''); const spells = computed(() => SPELLS.filter(s => !p.h.known.includes(s.id) && !p.h.cantrips.includes(s.id)).sort((a, b) => a.name.localeCompare(b.name))); const addSpell = () => { const s = SPELLS.find(x => x.name.toLowerCase() === sq.value.trim().toLowerCase()); if (s) { (s.lv ? p.h.known : p.h.cantrips).push(s.id); sq.value = '' } else if (sq.value.trim()) { O.value.spells.push({ id: 'q' + uid().slice(0, 6), name: sq.value.trim().slice(0, 40), lv: 1, kind: 'other', range: 60, time: 'action', text: '' }); sq.value = '' } }; const dropSpell = (id: string) => { p.h.known = p.h.known.filter(x => x !== id); p.h.cantrips = p.h.cantrips.filter(x => x !== id); p.h.prepared = p.h.prepared.filter(x => x !== id) }
const addItem = () => { const t = iq.value.trim().toLowerCase(); if (!t) return; const i = Object.values(ITEMS).find(x => x.name.toLowerCase() === t); if (i) { const have = p.h.inv.find(x => x.id === i.id && !x.eq); if (have) have.n++; else p.h.inv.push({ uid: uid(), id: i.id, n: 1 }) } else set('gear', [O.value.gear, iq.value.trim()].filter(Boolean).join('\n')); iq.value = '' }; const wear = (s: any) => { const i = item(s.id); const slot = i.kind === 'armor' ? 'armor' : i.kind === 'shield' ? 'off' : i.kind === 'weapon' ? 'main' : 'worn'; if (s.eq) { s.eq = undefined; return } if (slot !== 'worn') for (const q of p.h.inv) if (q.eq === slot) q.eq = undefined; s.eq = slot }
const slot = (i: number) => O.value.slots?.[i]; const setSlot = (i: number, v: number | undefined) => { const s = O.value.slots ? [...O.value.slots] : Array.from({ length: 9 }, (_, k) => S.value.slots[k] ?? 0); while (s.length < 9) s.push(0); s[i] = v ?? 0; set('slots', s.some(Boolean) ? s : undefined) }; const resist = (d: Damage) => { const l = [...(O.value.resist ?? [])]; const i = l.indexOf(d); i >= 0 ? l.splice(i, 1) : l.push(d); set('resist', l.length ? l : undefined) }
const BOX = computed(() => [['max', 'Hit points', S.value.max], ['ac', 'Armour class', S.value.ac], ['init', 'Initiative', S.value.init], ['speed', 'Speed', S.value.speed], ['prof', 'Proficiency', S.value.prof], ['pp', 'Passive sight', S.value.pp], ['nAttacks', 'Attacks a turn', S.value.nAttacks]] as [keyof Over, string, number][])
</script>
<template><div class="rec"><div class="left"><div class="fig"><Stage3D :look="look" /></div><template v-if="scan"><img :src="scan" class="scan" alt="Your own sheet"><button class="btn sm wide" @click="emit('scan', null)">Take the picture away</button></template><button v-else class="btn sm wide" @click="pic!.click()">Pin a picture of your sheet</button><input ref="pic" type="file" accept="image/*" hidden @change="emit('scan', ($event.target as HTMLInputElement).files?.[0] ?? null)"><details><summary>The figure on the table</summary><label class="lab">Body</label><select class="field" :value="h.race" aria-label="Body" @change="h.race = val($event); h.looks.skin = race(h.race).skins[1] ?? race(h.race).skins[0]; h.looks.hair = race(h.race).hairs[1] ?? race(h.race).hairs[0] ?? h.looks.hair"><option v-for="r in RACES" :key="r.id" :value="r.id">{{ r.name }}</option></select><Looks :l="h.looks" :race="h.race" /></details></div>
  <div class="form">
    <div class="head"><label class="big"><input v-model="h.name" maxlength="24" placeholder="Name" aria-label="Name" spellcheck="false"></label>
      <div class="line"><label style="flex:2">Class and level, as you write it<input :value="O.cls" placeholder="Rogue 5" aria-label="Class and level" @input="set('cls', val($event) || undefined)"></label><label>Plays as<select v-model="h.cls" aria-label="Plays as"><option v-for="c in CLASSES" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label class="s">Level<input v-model.number="h.level" type="number" min="1" max="20" aria-label="Level"></label></div>
      <div class="line"><label>Race<input :value="O.race" :placeholder="race(h.race).name" aria-label="Race" @input="set('race', val($event) || undefined)"></label><label>Background<input :value="O.bg" :placeholder="BACKGROUNDS.find(b => b.id === h.bg)?.name" aria-label="Background" @input="set('bg', val($event) || undefined)"></label><label>Alignment<input :value="O.align" aria-label="Alignment" @input="set('align', val($event) || undefined)"></label><label class="s">XP<input v-model.number="h.xp" type="number" min="0" aria-label="Experience"></label></div></div>
    <div class="boxes"><label v-for="b in BOX" :key="b[0]"><input type="number" :value="(O as any)[b[0]]" :placeholder="String(b[2])" :aria-label="b[1]" @input="set(b[0], n(val($event)))"><span>{{ b[1] }}</span></label></div>
    <div class="cols"><div><h3>Abilities</h3><table class="ab"><thead><tr><th /><th>Score</th><th>Mod</th><th>Save</th></tr></thead><tbody><tr v-for="a in ABILITIES" :key="a"><th>{{ ABILITY_NAME[a] }}</th><td><input v-model.number="h.base[a]" type="number" min="1" max="30" :aria-label="ABILITY_NAME[a]"></td><td class="m">{{ signed(S.mods[a]) }}</td><td><button type="button" class="tick" :class="{ on: saveP.includes(a) }" :aria-label="ABILITY_NAME[a] + ' save, proficient'" @click="togSave(a)" /><input type="number" class="nr" :value="O.saves?.[a]" :placeholder="signed(S.saves[a])" :aria-label="ABILITY_NAME[a] + ' save'" @input="setIn('saves', a, n(val($event)))"></td></tr></tbody></table>
      <h3>Spellcasting</h3><div class="line"><label>Ability<select :value="O.cast ?? ''" aria-label="Spellcasting ability" @change="set('cast', val($event) || undefined)"><option value="">by class</option><option v-for="a in ABILITIES" :key="a" :value="a">{{ ABILITY_NAME[a] }}</option></select></label><label class="s">Save DC<input type="number" :value="O.dc" :placeholder="String(S.dc)" aria-label="Spell save DC" @input="set('dc', n(val($event)))"></label><label class="s">Attack<input type="number" :value="O.spellHit" :placeholder="signed(S.spellHit)" aria-label="Spell attack" @input="set('spellHit', n(val($event)))"></label></div><div class="slots"><label v-for="i in 9" :key="i"><input type="number" min="0" max="9" :value="slot(i - 1)" :placeholder="String(S.slots[i - 1] ?? 0)" :aria-label="'Slots of level ' + i" @input="setSlot(i - 1, n(val($event)))"><span>{{ i }}</span></label></div></div>
      <div><h3>Skills</h3><div v-for="k in SKILL_IDS" :key="k" class="sk"><button type="button" class="pr" :class="{ p: h.skills.includes(k) || S.skills[k].p >= 1, e: h.expertise.includes(k) }" :aria-label="SKILL_NAME[k] + ': ' + (h.expertise.includes(k) ? 'expert' : h.skills.includes(k) ? 'proficient' : 'untrained')" @click="step(k)" /><span>{{ SKILL_NAME[k] }} <i>{{ SKILLS[k] }}</i></span><input type="number" class="nr" :value="O.skills?.[k]" :placeholder="signed(S.skills[k].v)" :aria-label="SKILL_NAME[k]" @input="setIn('skills', k, n(val($event)))"></div></div></div>
    <h3>Attacks</h3><table class="t at"><thead><tr><th>Name</th><th>To hit</th><th>Damage</th><th>Type</th><th>Reach or range</th><th /></tr></thead><tbody><tr v-for="(a, i) in O.attacks" :key="a.id"><td><input v-model="a.name" placeholder="Longsword" aria-label="Attack" maxlength="40"></td><td><input v-model.number="a.hit" type="number" aria-label="To hit"></td><td><input v-model="a.dmg" placeholder="1d8+3" aria-label="Damage" :class="{ no: badDice(a.dmg) }"></td><td><select v-model="a.type" aria-label="Damage type"><option v-for="d in DT" :key="d">{{ d }}</option></select></td><td class="rg"><select :value="a.ranged ? 'r' : 'm'" aria-label="Melee or ranged" @change="ranged(a, val($event) === 'r')"><option value="m">reach</option><option value="r">range</option></select><input v-if="a.ranged && a.range" v-model.number="a.range[0]" type="number" step="5" aria-label="Range"><input v-else v-model.number="a.reach" type="number" step="5" aria-label="Reach"></td><td><button type="button" class="del" aria-label="Strike out" @click="O.attacks.splice(i, 1)">×</button></td></tr></tbody></table><button type="button" class="btn sm" @click="addA">Another attack</button><span class="hint">Weapons in the pack attack by themselves. Write the ones whose numbers are your own.</span>
    <h3>Spells</h3><form class="add" @submit.prevent="addSpell"><input v-model="sq" list="rw-spells" placeholder="Write the name of a spell" aria-label="Spell"><datalist id="rw-spells"><option v-for="s in spells" :key="s.id" :value="s.name" /></datalist><button class="btn sm">Write it in</button></form><div class="chips"><button v-for="id in [...h.cantrips, ...h.known]" :key="id" type="button" class="chip s" :aria-label="'Strike out ' + spell(id).name" @click="dropSpell(id)">{{ spell(id).name }}<b>{{ spell(id).lv || 'c' }}</b> ×</button></div>
    <table v-if="O.spells.length" class="t at"><thead><tr><th>Your own spells</th><th>Level</th><th>What</th><th>Dice</th><th>Type</th><th>Save</th><th>Range</th><th>Area</th><th /></tr></thead><tbody><tr v-for="(s, i) in O.spells" :key="s.id"><td><input v-model="s.name" aria-label="Spell name" maxlength="40"><input v-model="s.text" class="txt" placeholder="What it does" aria-label="What it does" maxlength="400"></td><td><input v-model.number="s.lv" type="number" min="0" max="9" aria-label="Spell level"></td><td><select v-model="s.kind" aria-label="Kind"><option value="attack">attack</option><option value="save">save</option><option value="heal">healing</option><option value="other">other</option></select></td><td><input v-model="s.dmg" placeholder="2d8" aria-label="Dice" :class="{ no: badDice(s.dmg) }"></td><td><select v-model="s.type" aria-label="Type"><option v-for="d in DT" :key="d">{{ d }}</option></select></td><td><select v-model="s.save" aria-label="Save" :disabled="s.kind !== 'save'"><option v-for="a in ABILITIES" :key="a" :value="a">{{ a }}</option></select></td><td><input v-model.number="s.range" type="number" step="5" aria-label="Range"></td><td class="rg"><select v-model="s.area" aria-label="Area"><option :value="undefined">one</option><option value="sphere">sphere</option><option value="cone">cone</option><option value="line">line</option><option value="cube">cube</option></select><input v-if="s.area" v-model.number="s.size" type="number" step="5" aria-label="Size"></td><td><button type="button" class="del" aria-label="Strike out" @click="O.spells.splice(i, 1)">×</button></td></tr></tbody></table><button type="button" class="btn sm" @click="addS">A spell of your own</button>
    <h3>Features and feats</h3><div v-for="(f, i) in O.feats" :key="i" class="ft"><input v-model="f.name" placeholder="Name" aria-label="Feature" maxlength="60"><label>Uses<input type="number" min="0" max="40" :value="f.uses" placeholder="any" aria-label="Uses" @input="f.uses = n(val($event))"></label><select v-model="f.rest" aria-label="Comes back after"><option value="short">short rest</option><option value="long">long rest</option></select><button type="button" class="del" aria-label="Strike out" @click="O.feats.splice(i, 1)">×</button><textarea v-model="f.text" rows="2" placeholder="What it does" aria-label="What it does" maxlength="900" /></div><button type="button" class="btn sm" @click="addF">Another feature</button><span class="hint">{{ CLASSES.find(c => c.id === h.cls)?.name }} features are already in play, for level {{ O.clsLv ?? h.level }}.</span>
    <div class="cols"><div><h3>Pack</h3><form class="add" @submit.prevent="addItem"><input v-model="iq" list="rw-items" placeholder="Write a thing you carry" aria-label="Item"><datalist id="rw-items"><option v-for="i in Object.values(ITEMS).filter(i => i.id !== 'unarmed')" :key="i.id" :value="i.name" /></datalist><button class="btn sm">Write it in</button></form><div v-for="(s, i) in h.inv" :key="s.uid" class="iv"><span class="cut">{{ item(s.id).name }}</span><button v-if="['weapon', 'armor', 'shield', 'ring', 'wondrous', 'focus'].includes(item(s.id).kind)" type="button" class="wr" :class="{ on: s.eq }" @click="wear(s)">{{ s.eq ? 'worn' : 'wear' }}</button><input v-model.number="s.n" type="number" min="1" :aria-label="item(s.id).name + ', how many'"><button type="button" class="del" aria-label="Strike out" @click="h.inv.splice(i, 1)">×</button></div><label class="lab">Other things</label><textarea :value="O.gear" rows="3" aria-label="Other things" @input="set('gear', val($event) || undefined)" /><div class="line"><label class="s">Gold<input v-model.number="h.gold" type="number" min="0" aria-label="Gold"></label><label class="s">Hit points now<input v-model.number="h.hp" type="number" min="0" aria-label="Hit points now"></label><label class="s">Crits on<input type="number" min="15" max="20" :value="O.crit" placeholder="20" aria-label="Critical from" @input="set('crit', n(val($event)))"></label></div></div>
      <div><h3>The rest</h3><label class="lab">Languages and proficiencies</label><textarea :value="O.langs" rows="2" aria-label="Languages" @input="set('langs', val($event) || undefined)" /><label class="lab">Resists</label><div class="chips"><button v-for="d in DT" :key="d" type="button" class="chip s" :class="{ on: O.resist?.includes(d) }" @click="resist(d)">{{ d }}</button></div><label class="lab">Story (the Dungeon Master reads it)</label><textarea v-model="h.story" rows="3" aria-label="Story" maxlength="2000" /><label class="lab">Notes</label><textarea v-model="h.notes" rows="3" aria-label="Notes" maxlength="4000" /></div></div>
  </div></div></template>
<style scoped>
.rec{display:grid;grid-template-columns:minmax(200px,270px) minmax(0,1fr);gap:30px;align-items:start}.left{position:sticky;top:0;display:grid;gap:8px}.fig{height:330px;background:var(--spot)}.scan{width:100%;border:2px solid var(--ink);max-height:60vh;object-fit:contain;background:#fff}details summary{cursor:pointer;font-weight:500;padding:6px 0;text-decoration:underline;text-underline-offset:4px}
input,select,textarea{font:inherit;color:var(--ink);background:none;border:0;border-bottom:2px solid var(--ink);border-radius:0;padding:3px 5px;width:100%;min-width:0;outline:none;min-height:32px;-moz-appearance:textfield}input:focus,select:focus,textarea:focus{background:#fff;border-color:var(--spot)}input::placeholder,textarea::placeholder{color:#9a9c9b}input::-webkit-inner-spin-button{display:none}textarea{border:2px solid var(--ink);resize:vertical;line-height:1.3;padding:6px 8px}.no{background:#f7d9d2!important;border-color:var(--bad)!important}
h3{margin:24px 0 8px;border-bottom:3px solid var(--ink);padding-bottom:4px}label{font-size:14.5px;color:var(--ink2);display:block;line-height:1.2}.line{display:flex;gap:16px;margin-top:9px}.line label{flex:1;min-width:0}.line .s{flex:0 0 92px}.line input,.line select{font-size:18px;color:var(--ink)}.big input{font:800 44px/1 var(--serif);border-bottom-width:4px;padding:0 0 6px}
.boxes{display:grid;grid-template-columns:repeat(7,1fr);border:2px solid var(--ink);margin-top:16px}.boxes label{border-right:2px solid var(--ink);text-align:center;padding-bottom:6px;font-size:14px}.boxes label:last-child{border:0}.boxes input{border:0;text-align:center;font:800 36px/1 var(--serif);height:52px;padding:0}.boxes span{display:block}
.cols{display:grid;grid-template-columns:1fr 1fr;gap:34px}.ab{width:100%;border-collapse:collapse}.ab th{text-align:left;font:600 17px var(--ui);padding:3px 0}.ab thead th{font-size:14px;color:var(--ink2);font-weight:400}.ab td{padding:2px 8px 2px 0}.ab td input{font:700 20px/1 var(--serif);text-align:center;width:62px}.ab .m{font:800 25px/1 var(--serif);width:48px}.ab td:last-child{display:flex;align-items:center;gap:7px}button.tick{flex:none}.nr{width:56px!important;text-align:center;font-weight:600!important}
.slots{display:grid;grid-template-columns:repeat(9,1fr);border:2px solid var(--ink);margin-top:12px}.slots label{text-align:center;border-right:1px solid var(--ink)}.slots label:last-child{border:0}.slots input{border:0;text-align:center;font:700 21px/1 var(--serif)}.slots span{display:block;background:var(--ink);color:var(--paper)}
.sk{display:flex;align-items:center;gap:9px;min-height:28px}.sk span{flex:1;font-size:16.5px}.sk i{font-style:normal;color:var(--ink3);font-size:14px}.sk input{min-height:26px;padding:0}.pr{width:17px;height:17px;border:2px solid var(--ink);flex:none}.pr.p{background:var(--ink)}.pr.e{background:var(--spot);box-shadow:inset 0 0 0 3px var(--ink)}
.at td{padding:3px 8px 3px 0}.at td:nth-child(2) input,.at td:nth-child(3) input,.at td:nth-child(4) input{min-width:58px}.at td:first-child{width:28%}.rg{display:flex;gap:4px}.rg select{width:auto}.txt{font-size:15px;border-bottom-width:1px}.del{width:30px;height:30px;text-align:center;font-size:23px;line-height:1;color:var(--ink2)}.del:hover{background:var(--bad);color:#fff}.hint{font-size:14.5px;color:var(--ink2);margin-left:12px}.add{display:flex;gap:8px;margin-bottom:8px;max-width:460px}.add .btn{flex:none}.chip b{font-weight:600}.btn.sm{margin-top:8px}.add .btn.sm{margin:0}
.ft{display:grid;grid-template-columns:1fr 110px 130px 32px;gap:4px 12px;margin-bottom:11px;align-items:end}.ft>input{font-weight:600;font-size:17px}.ft label{display:flex;align-items:baseline;gap:6px}.ft textarea{grid-column:1/-1}.iv{display:flex;align-items:center;gap:8px;border-bottom:1px solid var(--line)}.iv span{flex:1}.iv input{width:52px;border:0;text-align:center}.wr{font-size:15px;color:var(--ink3);padding:2px 8px}.wr.on{background:var(--ink);color:var(--paper)}
@media(max-width:1000px){.rec{grid-template-columns:1fr}.left{position:static;grid-template-columns:1fr 1fr;align-items:start}.fig{height:210px}}
@media(max-width:700px){.cols{grid-template-columns:1fr;gap:0}.boxes{grid-template-columns:repeat(4,1fr)}.boxes label{border-bottom:2px solid var(--ink)}.line{flex-wrap:wrap;gap:8px 14px}.line label{flex:1 1 40%!important}.at{display:block;overflow-x:auto}.at td{min-width:92px}.ft{grid-template-columns:1fr 90px 32px}.ft select{grid-row:2}.big input{font-size:34px}.left{grid-template-columns:1fr}}
</style>
